          "title": "Host Email"
        },
        "start_time": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Start time in ISO format.",
          "title": "Start Time"
        },
        "duration": {
          "default": 60,
          "description": "Duration in minutes (default 60).",
          "title": "Duration",
          "type": "integer"
        },
        "timezone": {
          "default": "America/Los_Angeles",
          "description": "Timezone (default America/Los_Angeles).",
          "title": "Timezone",
          "type": "string"
        },
        "agenda": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Meeting agenda/description.",
          "title": "Agenda"
