    "name": "docusign_create_envelope_from_template",
    "description": "Create an envelope from a template and optionally send it.\n\nArgs:\n    template_id: ID of the template to use.\n    signer_name: Name of the primary signer.\n    signer_email: Email of the primary signer.\n    email_subject: Email subject line (optional).\n    status: Envelope status - 'sent' or 'created' (draft).\n    signers_json: Optional JSON string containing a list of additional signers.\n        Each signer object can have: name, email, recipient_id, routing_order, role_name.\n        Example: '[{\"name\": \"Jane Doe\", \"email\": \"jane@example.com\", \"routing_order\": \"2\"}]'\n    field_values_json: Optional JSON string containing template field values as key-value pairs.\n        Example: '{\"contract_amount\": \"50000\", \"term_months\": \"12\"}'\n    email_body: Alias for email_blurb.\n    signer_role_name: Optional template role name for the primary signer.\n\nReturns:\n    JSON string with created envelope details.",
    "parameters": {
      "properties": {
        "template_id": {
          "description": "ID of the template to use.",
          "title": "Template Id",
          "type": "string"
        },
        "signer_name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Name of the primary signer.",
          "title": "Signer Name"
        },
        "signer_email": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Email of the primary signer.",
          "title": "Signer Email"
        },
        "email_subject": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Email subject line (optional).",
          "title": "Email Subject"
        },
        "status": {
          "default": "sent",
          "description": "Envelope status - 'sent' or 'created' (draft).",
          "title": "Status",
          "type": "string"
        },
        "signers_json": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional JSON string containing a list of additional signers.\nEach signer object can have: name, email, recipient_id, routing_order, role_name.\nExample: '[{\"name\": \"Jane Doe\", \"email\": \"jane@example.com\", \"routing_order\": \"2\"}]'",
          "title": "Signers Json"
        },
        "field_values_json": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional JSON string containing template field values as key-value pairs.\nExample: '{\"contract_amount\": \"50000\", \"term_months\": \"12\"}'",
          "title": "Field Values Json"
        },
        "email_body": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Alias for email_blurb.",
          "title": "Email Body"
        },
        "email_blurb": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Email Blurb"
        },
        "signer_role_name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional template role name for the primary signer.",
          "title": "Signer Role Name"
        }
      },
      "required": [
        "template_id",
        "signer_name",
        "signer_email",
        "email_subject",
        "status",
        "signers_json",
        "field_values_json",
